cat > /app/hierarchical_model.stan << 'EOF'
data {
  int<lower=1> N;           // number of observations
  int<lower=0> y[N];        // successes
  int<lower=1> n[N];        // trials
}
parameters {
  real<lower=0> alpha;      // Beta distribution parameter
  real<lower=0> beta;       // Beta distribution parameter
  real<lower=0, upper=1> theta[N];  // success probabilities for each observation
}
model {
  // Prior: (alpha, beta) proportional to (alpha + beta)^(-5/2)
  target += -2.5 * log(alpha + beta);

  // Likelihood
  for (i in 1:N) {
    y[i] ~ binomial(n[i], theta[i]);
    theta[i] ~ beta(alpha, beta);
  }
}
EOF
cat /app/hierarchical_model.stan

